"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { useParams } from "next/navigation";
import { getPostBySlug, Post } from "@/lib/firestore";
import { posts as fallbackPosts } from "@/lib/posts";

// Parse inline markdown (bold, italic, links, code) into JSX
function parseInlineMarkdown(text: string): (string | JSX.Element)[] {
  const parts: (string | JSX.Element)[] = [];
  let remaining = text;
  let keyIdx = 0;

  while (remaining.length > 0) {
    // Check for links [text](url)
    const linkMatch = remaining.match(/^\[([^\]]+)\]\(([^)]+)\)/);
    if (linkMatch) {
      const [full, linkText, url] = linkMatch;
      const isInternal = url.startsWith("/");
      if (isInternal) {
        parts.push(
          <Link key={keyIdx++} href={url} className="text-[--accent] hover:underline">
            {linkText}
          </Link>
        );
      } else {
        parts.push(
          <a key={keyIdx++} href={url} className="text-[--accent] hover:underline" target="_blank" rel="noopener noreferrer">
            {linkText}
          </a>
        );
      }
      remaining = remaining.slice(full.length);
      continue;
    }

    // Check for bold **text**
    const boldMatch = remaining.match(/^\*\*([^*]+)\*\*/);
    if (boldMatch) {
      const [full, boldText] = boldMatch;
      parts.push(<strong key={keyIdx++}>{boldText}</strong>);
      remaining = remaining.slice(full.length);
      continue;
    }

    // Check for italic *text*
    const italicMatch = remaining.match(/^\*([^*]+)\*/);
    if (italicMatch) {
      const [full, italicText] = italicMatch;
      parts.push(<em key={keyIdx++}>{italicText}</em>);
      remaining = remaining.slice(full.length);
      continue;
    }

    // Check for inline code `code`
    const codeMatch = remaining.match(/^`([^`]+)`/);
    if (codeMatch) {
      const [full, codeText] = codeMatch;
      parts.push(<code key={keyIdx++} className="bg-gray-100 px-1 rounded text-sm font-mono">{codeText}</code>);
      remaining = remaining.slice(full.length);
      continue;
    }

    // No match, add next character
    parts.push(remaining[0]);
    remaining = remaining.slice(1);
  }

  // Merge adjacent strings
  const merged: (string | JSX.Element)[] = [];
  let currentStr = "";
  for (const part of parts) {
    if (typeof part === "string") {
      currentStr += part;
    } else {
      if (currentStr) {
        merged.push(currentStr);
        currentStr = "";
      }
      merged.push(part);
    }
  }
  if (currentStr) merged.push(currentStr);
  return merged.length > 0 ? merged : [text];
}

// Parse markdown images ![alt](url) into JSX
function parseImages(text: string): (string | JSX.Element)[] {
  const imageRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
  const parts: (string | JSX.Element)[] = [];
  let lastIndex = 0;
  let match;
  let keyIndex = 0;

  while ((match = imageRegex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      parts.push(text.slice(lastIndex, match.index));
    }
    const [, alt, url] = match;
    parts.push(
      <figure key={keyIndex++} className="my-8">
        <div className="relative w-full border border-[--border]">
          <Image
            src={url}
            alt={alt}
            width={800}
            height={500}
            className="w-full h-auto"
            unoptimized={url.startsWith("http")}
          />
        </div>
        {alt && (
          <figcaption className="text-sm text-[--muted] mt-2 text-center">
            {alt}
          </figcaption>
        )}
      </figure>
    );
    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < text.length) {
    parts.push(text.slice(lastIndex));
  }

  return parts.length > 0 ? parts : [text];
}

export default function BlogPost() {
  const params = useParams();
  const slug = params.slug as string;
  const [post, setPost] = useState<Post | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    async function loadPost() {
      try {
        // Try Firestore first
        const firestorePost = await getPostBySlug(slug);
        if (firestorePost) {
          setPost(firestorePost);
        } else {
          // Fall back to hardcoded posts
          const fallback = fallbackPosts[slug];
          if (fallback) {
            // Convert hardcoded format to Firestore format
            let content = fallback.content;
            if (fallback.images) {
              fallback.images.forEach((img, i) => {
                content = content.replace(
                  `[IMAGE:${i}]`,
                  `![${img.alt}](${img.src})`
                );
              });
            }
            setPost({
              slug: fallback.slug,
              title: fallback.title,
              date: fallback.date,
              content,
              isProject: fallback.isProject,
              parent: fallback.parent,
              status: "published",
            } as Post);
          } else {
            setNotFound(true);
          }
        }
      } catch (error) {
        console.error("Error loading post:", error);
        // Try fallback on error
        const fallback = fallbackPosts[slug];
        if (fallback) {
          let content = fallback.content;
          if (fallback.images) {
            fallback.images.forEach((img, i) => {
              content = content.replace(
                `[IMAGE:${i}]`,
                `![${img.alt}](${img.src})`
              );
            });
          }
          setPost({
            slug: fallback.slug,
            title: fallback.title,
            date: fallback.date,
            content,
            isProject: fallback.isProject,
            parent: fallback.parent,
            status: "published",
          } as Post);
        } else {
          setNotFound(true);
        }
      } finally {
        setLoading(false);
      }
    }

    loadPost();
  }, [slug]);

  const renderContent = () => {
    if (!post) return null;

    // First parse images, then for text parts parse inline markdown
    const parts = parseImages(post.content);

    return parts.map((part, i) => {
      if (typeof part !== "string") {
        return part; // Already a JSX element (image)
      }

      return part.split("\n\n").map((paragraph, j) => {
        if (!paragraph.trim()) return null;

        if (paragraph.startsWith("# ") && !paragraph.startsWith("## ")) {
          return (
            <h1 key={`${i}-${j}`} className="text-[--foreground] font-bold mt-8 mb-4 text-2xl">
              {parseInlineMarkdown(paragraph.replace("# ", ""))}
            </h1>
          );
        }
        if (paragraph.startsWith("## ")) {
          return (
            <h2 key={`${i}-${j}`} className="text-[--foreground] font-bold mt-8 mb-4 text-xl">
              {parseInlineMarkdown(paragraph.replace("## ", ""))}
            </h2>
          );
        }
        if (paragraph.startsWith("├─") || paragraph.startsWith("└─") || paragraph.startsWith("│")) {
          const lines = paragraph.split("\n");
          return (
            <pre key={`${i}-${j}`} className="text-[--foreground] my-1 whitespace-pre-wrap">
              {lines.map((line, k) => (
                <span key={k}>
                  {parseInlineMarkdown(line)}
                  {k < lines.length - 1 && "\n"}
                </span>
              ))}
            </pre>
          );
        }
        if (paragraph.match(/^\d+\./)) {
          return (
            <p key={`${i}-${j}`} className="text-[--foreground] my-2 pl-4">
              {parseInlineMarkdown(paragraph)}
            </p>
          );
        }
        if (paragraph.startsWith("- ") || paragraph.startsWith("* ")) {
          return (
            <li key={`${i}-${j}`} className="text-[--foreground] my-1 ml-4">
              {parseInlineMarkdown(paragraph.slice(2))}
            </li>
          );
        }
        return (
          <p key={`${i}-${j}`} className="text-[--foreground] my-4 leading-relaxed">
            {parseInlineMarkdown(paragraph)}
          </p>
        );
      });
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[--background] flex items-center justify-center">
        <p className="text-[--muted]">Loading...</p>
      </div>
    );
  }

  if (notFound || !post) {
    return (
      <div className="min-h-screen bg-[--background] flex flex-col items-center justify-center">
        <h1 className="text-2xl font-bold text-[--foreground] mb-4">Not Found</h1>
        <Link href="/" className="text-[--accent] hover:underline">
          ← back to home
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[--background]">
      <main className="mx-auto max-w-3xl px-6 py-12">
        <Link
          href="/"
          className="text-[--muted] hover:text-[--accent] text-sm"
        >
          ← back
        </Link>

        <article className="mt-8">
          <header className="mb-8 pb-4 border-b border-[--border]">
            <h1 className="text-2xl font-bold text-[--foreground] mb-2">{post.title}</h1>
            {post.date && <time className="text-sm text-[--muted]">{post.date}</time>}
            {post.parent && (
              <div className="mt-2">
                <Link href={`/blog/${post.parent}`} className="text-sm text-[--accent]">
                  ← Part of: {post.parent.replace(/-/g, " ")}
                </Link>
              </div>
            )}
          </header>

          <div className="prose-terminal">
            {renderContent()}
          </div>
        </article>

        <footer className="mt-16 pt-8 border-t border-[--border]">
          <Link href="/" className="text-[--muted] hover:text-[--accent] text-sm">
            ← back to home
          </Link>
        </footer>
      </main>
    </div>
  );
}
